# Remaining planned guides. No prices, no certification, no UPF/cooling-tech claims.
def G(slug,title,desc,h1,intro,secs,faqs): return dict(slug=slug,title=title,desc=desc,h1=h1,intro=intro,sections=secs,faqs=faqs)
CTA='<p>Want a design for your crew? <a href="/#design">Send your logo</a> and crew size for a free design within 24 hours.</p>'
MORE5=[
G('what-do-plumbers-wear','What do plumbers wear to work?','What plumbers wear on the job: shirts, layers, pants, footwear and what to print so customers recognise your company.',
'What do plumbers <em>wear</em> to work?','Plumbers work in tight, wet spaces and then walk into a customer\'s home. Their clothes have to survive the job and still look professional at the door.',
[('The everyday kit','<p>Most plumbers wear a durable work shirt or polo, sturdy work pants, and boots with good grip. Long sleeves protect the arms in crawl spaces and under sinks. A cap keeps sun and dust off outdoors. Many keep a spare shirt in the truck.</p>'),
('Fabric matters','<p>Wet work favours fabric that dries quickly. Polyester dries faster than heavy cotton, which stays damp. Some plumbers still prefer cotton for softness, so it comes down to the job and personal choice. Read <a href="/guides/polyester-vs-cotton-work-shirts">polyester vs cotton work shirts</a>.</p>'),
('Look professional at the door','<p>A matching shirt with your company name and phone number tells customers who you are before you speak. See <a href="/guides/what-to-put-on-the-back-of-a-work-shirt">what to put on the back of a work shirt</a> and our <a href="/plumbing">plumbing uniforms</a>.</p>'+CTA)],
[('Do plumbers wear uniforms?','Many plumbing companies do. A matching uniform helps customers recognise the technician and builds trust in their home.'),('What should plumbers not wear?','Loose, dangling clothing that can catch on tools or pipes, and open-toe shoes.'),('Should plumbers wear long sleeves?','Many do for protection in crawl spaces and under sinks, though some choose short sleeves in heat.')]),
G('what-kind-of-shirts-do-mechanics-wear','What kind of shirts do mechanics wear?','What shirts mechanics wear in the shop: work shirts, tees, button-ups and what to consider for oil, washing and brand look.',
'What kind of shirts do mechanics <em>wear</em>?','Mechanics deal with oil, grease and constant washing. Shirts have to hold up and still represent the shop.',
[('Common choices','<p>Mechanics typically wear work shirts, button-up uniform shirts, tees or polos, often with the shop name on the chest and the mechanic\'s name on a patch or print. Many shops supply uniforms so the team looks consistent.</p>'),
('Polyester or heavy cotton','<p>Heavy cotton is a classic shop fabric and many mechanics like it. Polyester dries faster and holds colour through frequent washing, and a sublimated print does not crack. Stains can still be hard to remove from either. See our <a href="/mechanic-shirts">mechanic shirts</a>.</p>'),
('What to print','<p>Shop name and logo on the chest, mechanic names, and your phone number on the back so customers and passers-by can find you.</p>'+CTA)],
[('Do mechanics wear uniforms?','Many shops do. Uniforms look professional and make staff easy to identify.'),('What colour shirts hide oil best?','Darker colours and busy patterns hide stains better than light colours.'),('Can I put the mechanic\'s name on the shirt?','Yes. Names or numbers can be printed on the chest or sleeve.')]),
G('what-do-painters-wear','What do painters wear to work?','What house painters wear: clothes, fabric choices, and why many crews use branded shirts as moving advertising.',
'What do painters <em>wear</em> to work?','Painters expect to get paint on their clothes, so the usual advice is simple, comfortable and replaceable. But a branded shirt also advertises your business on every job.',
[('The practical kit','<p>Most painters wear comfortable work pants, a light shirt that breathes, and shoes they do not mind ruining. Many keep a separate set of clothes for messy work and a clean branded shirt for meetings and estimates.</p>'),
('Fabric','<p>Lightweight shirts keep painters cooler on ladders and in closed rooms. Polyester dries quickly if it gets wet. Paint can stain any fabric, so many crews rotate shirts.</p>'),
('Use your shirt as advertising','<p>Neighbours see your crew at the house for days. A shirt with your company name and phone number turns that into free advertising. See <a href="/guides/how-to-uniform-a-trade-crew">how to uniform a trade crew</a>.</p>'+CTA)],
[('Do painters wear white?','Traditionally yes, white hides paint splatter and reflects heat, but many crews now wear brand colours.'),('Should painters wear long sleeves?','Long sleeves protect arms from splatter and sun on exterior jobs.'),('Can I get branded shirts for a small painting crew?','Yes. Tell us your crew size and we will confirm the minimum.')]),
G('best-work-shirts-for-hot-weather','Best work shirts for hot weather','How to choose work shirts for hot weather: fabric, fit, sleeve length, colour and what to avoid on hot job sites.',
'Best work shirts for <em>hot weather</em>','Hot weather work is about staying covered and dry, not just wearing less. The right shirt makes a long day easier.',
[('What to look for','<p>Lightweight fabric that dries quickly, a relaxed fit that lets air move, and a design without heavy seams. Moisture-wicking polyester is a common choice because it carries sweat away from the skin and dries faster than heavy cotton.</p>'),
('Short or long sleeves','<p>Long sleeves cover the arms from direct sun and many outdoor crews prefer them when the fabric is light. Short sleeves can feel cooler in still air. Choose what your crew will actually wear. See <a href="/long-sleeve-work-shirts">long sleeve work shirts</a>.</p>'),
('Colour','<p>Lighter colours reflect more heat than very dark ones, though a light shirt shows dirt faster. Many crews choose mid-tones with dark accents.</p>'+CTA)],
[('Are long sleeves hotter?','Not necessarily. A lightweight, breathable long sleeve can feel comfortable and protects from sun.'),('Is polyester good in heat?','Moisture-wicking polyester dries quickly, which many workers prefer in heat. Comfort is personal.'),('What colour is coolest?','Lighter colours reflect more sunlight than dark ones.')]),
G('what-is-moisture-wicking-fabric','What is moisture wicking fabric?','Moisture wicking fabric explained in plain words: how it moves sweat, what it is made of, and when it suits work shirts.',
'What is <em>moisture wicking</em> fabric?','Moisture wicking is a fabric trait that moves sweat away from your skin so it can spread out and dry faster.',
[('How it works in plain words','<p>Synthetic fibres such as polyester do not soak up much water. Instead, sweat travels along the surface and spreads over a larger area of fabric, where it evaporates sooner. That is why a wicking shirt feels drier than a soaked cotton one.</p>'),
('Where it helps','<p>Outdoor trades, long shifts and humid weather are where it helps most. It also dries after washing quickly. See <a href="/guides/best-work-shirts-for-hot-weather">best work shirts for hot weather</a>.</p>'),
('Limits','<p>Wicking does not make you cool by itself, and no fabric removes heat in a hot attic. Fit, ventilation and breaks matter too. Our full-print shirts are polyester, which is the kind of fibre commonly used for wicking.</p>'+CTA)],
[('Is moisture wicking the same as breathable?','They are related but not the same. Wicking moves sweat; breathable describes airflow through the fabric.'),('Does polyester wick moisture?','Polyester is commonly used for moisture wicking fabrics.'),('Does cotton wick?','Cotton absorbs moisture and holds it, so it tends to stay wet longer.')]),
G('polyester-vs-cotton-work-shirts','Polyester vs cotton work shirts','Polyester vs cotton for work shirts: drying time, comfort, colour, printing and which suits your trade.',
'Polyester vs cotton <em>work shirts</em>','Both fabrics work. The right one depends on the job, the climate and what you want printed.',
[('Polyester','<p>Dries quickly, resists shrinking and holds colour through many washes. It suits wet, hot or sweaty work and full-print designs, because sublimation dyes the fibre itself. See <a href="/guides/sublimation-vs-screen-print">sublimation vs screen print</a>.</p>'),
('Cotton','<p>Soft, familiar and comfortable for many people. It absorbs moisture and takes longer to dry, and it can shrink. Cotton is popular for classic logo tees and polos.</p>'),
('Which should you choose','<p>For outdoor and wet trades, many crews choose polyester. For office staff or a classic look, cotton polos are common. Many businesses use both. We offer a full-print polyester line and a classic logo line.</p>'+CTA)],
[('Is polyester hotter than cotton?','Not always. A lightweight wicking polyester can feel drier in sweat, while thick fabrics of either type feel warm.'),('Does polyester shrink?','Polyester generally shrinks less than cotton.'),('Can you sublimate on cotton?','Sublimation works on polyester. Cotton uses other print methods.')]),
G('dye-sublimation-shirts-explained','Dye sublimation shirts explained','Dye sublimation shirts explained: how the print is made, why it does not crack or peel, and what it needs to work.',
'Dye sublimation shirts <em>explained</em>','Sublimation is a way to print where the ink becomes part of the fabric instead of sitting on top.',
[('How it works','<p>The design is printed onto special paper, then pressed onto polyester with heat. The dye turns to gas and bonds with the polyester fibres. The print becomes part of the fabric, so it does not crack or peel like a surface print.</p>'),
('What it allows','<p>Because the whole panel can be printed, sublimation allows full-coverage designs, gradients and fine detail across the shirt, sleeves and hood.</p>'),
('What it needs','<p>It works on polyester, so it is not for cotton. White and light fabric shows colours best. See <a href="/guides/polyester-vs-cotton-work-shirts">polyester vs cotton</a>.</p>'+CTA)],
[('Does sublimation fade?','It is designed to hold up through repeated washing, though any print can fade with harsh care. Follow the care label.'),('Does sublimation feel different?','The print is in the fabric, so it does not add a layer on the surface.'),('Is sublimation good for logos?','Yes, especially large or colourful logos.')]),
G('pressure-washing-clothing-guide','What to wear when pressure washing','What to wear for pressure washing: clothing, boots, eye and hearing protection, and how to stay dry and visible.',
'What to wear when <em>pressure washing</em>','Pressure washing throws spray and debris. Dress for wet, sun and safety.',
[('Clothing','<p>Moisture-wicking long sleeves and quick-drying pants dry faster than heavy cotton. Waterproof boots with good grip help on wet surfaces.</p>'),
('Safety gear','<p>Eye protection and hearing protection are common, and gloves help with grip. Follow your equipment maker\'s guidance. Skin can be injured by high-pressure water, so never point the wand at anyone.</p>'),
('Look like a pro','<p>A branded shirt with your name and number on the back advertises your business at every driveway. See <a href="/pressure-washing">pressure washing shirts</a>.</p>'+CTA)],
[('Should I wear long sleeves?','Many pressure washers do, for sun and spray coverage.'),('What footwear is best?','Waterproof boots with grip.'),('Can I print my services on the shirt?','Yes, on the back.')]),
G('hvac-technician-uniform-ideas','HVAC technician uniform ideas','HVAC technician uniform ideas: shirts, hoodies, colours, what to print and how to look professional in customers\' homes.',
'HVAC technician <em>uniform ideas</em>','A good HVAC uniform works in an attic and still looks professional at the front door.',
[('What techs wear','<p>Lightweight long sleeves for summer, a hoodie or layer for winter call-outs, a cap for outdoor work and a polo for estimators.</p>'),
('Design ideas','<ul><li>A blue-and-white theme that suggests cooling, or warm accents for heating.</li><li>A clean chest logo with your phone number big on the back.</li><li>Technician names for a personal touch.</li><li>Colours that match your vans.</li></ul>'),
('Plan the order','<p>Order before the busy season so new hires start in uniform. See <a href="/hvac">HVAC uniforms</a>.</p>'+CTA)],
[('What do HVAC techs wear?','Work shirts or polos, long sleeves in summer, layers in winter, and a cap.'),('Should HVAC uniforms be dark?','Dark hides dirt but absorbs heat. Mid-tones are a common compromise.'),('Can I add my licence number?','Yes, on the sleeve or back, if you want it shown.')]),
G('what-to-wear-for-pest-control','What to wear for pest control','What pest control technicians wear: clothing, footwear and why a branded uniform matters for trust.',
'What to wear for <em>pest control</em>','Pest control technicians go into homes and crawl spaces. Clothing needs to be practical and the uniform needs to build trust.',
[('Practical kit','<p>Long sleeves and long pants protect against dirt, insects and product contact, plus sturdy closed shoes. Techs use any protective equipment required by the products they apply and local rules; follow product labels and your licence requirements.</p>'),
('Trust at the door','<p>Homeowners want to know who is entering their home. A clean uniform with your company name and tech name helps. See <a href="/pest-control-uniforms">pest control uniforms</a>.</p>'),
('What to print','<p>Company name and logo on the chest, technician name, and phone number on the back.</p>'+CTA)],
[('Do pest control technicians wear uniforms?','Most do, because it builds trust when entering homes.'),('What protective gear is required?','It depends on the products used and local rules. Follow labels and your licence guidance.'),('Can I add technician names?','Yes.')]),
G('custom-fishing-jersey-design-ideas','Custom fishing jersey design ideas','Custom fishing jersey design ideas for teams, charters and tournaments: colours, patterns, logos and layout.',
'Custom fishing jersey <em>design ideas</em>','A good fishing jersey looks great on the dock, in photos and from a boat.',
[('Themes','<ul><li>Water and wave patterns in blues and greens.</li><li>Fish silhouettes or scales as a repeating pattern.</li><li>Bold team colours with contrast panels.</li><li>Camo-inspired patterns for freshwater or bass teams.</li></ul>'),
('Layout','<p>Put the team or charter name on the chest, sponsor logos on the sleeves and a phone number or website on the back. Keep logos readable at a distance.</p>'),
('Ordering','<p>Tell us your colours, logos and quantity and we will send a free design. See <a href="/custom-fishing-shirts">custom fishing shirts</a>.</p>'+CTA)],
[('Can I put sponsor logos on a fishing jersey?','Yes. Sleeves and chest are common spots.'),('Can every angler have their own name?','Yes. Names or numbers can be printed per person.'),('What fabric is used?','Polyester, which dries quickly and holds sublimated colour.')]),
]
